import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';
import { Keypair } from '@solana/web3.js';
import bs58 from 'bs58';
import assert from 'node:assert/strict';
const env = { ...process.env }; delete env.SOLANA_SECRET_KEY; delete env.REQUIRE_CONFIRM; delete env.THREE_WS_BASE;
const c = new Client({ name: 'x-content-trial', version: '1' });
await c.connect(new StdioClientTransport({ command: 'npx', args: ['-y', '@three-ws/three-token-mcp@latest'], env }));
const read = (r) => JSON.parse(r.content[0].text);
try {
  const burn = (await c.listTools()).tools.find((t) => t.name === 'three_burn');
  assert.ok(burn, 'three_burn is not listed');
  assert.equal(burn.annotations?.destructiveHint, true, 'three_burn is not flagged destructive');
  assert.equal(burn.annotations?.readOnlyHint, false);
  const gated = read(await c.callTool({ name: 'three_burn', arguments: { usd: 0.01 } }));
  assert.equal(gated.error, 'confirmation_required', 'three_burn ran without confirm: true');
  const price = read(await c.callTool({ name: 'three_price', arguments: { usd: 1 } }));
  assert.equal(price.mint, 'FeMbDoX7R1Psc4GEcvJdsbNbZA3bfztcyDCatJVJpump', 'three_price did not resolve canonical $THREE');
  assert.ok(price.price_usd > 0, 'three_price returned no live price');
  const empty = bs58.encode(Keypair.generate().secretKey);
  const dry = read(await c.callTool({ name: 'three_burn', arguments: { usd: 0.01, confirm: true, secret: empty } }));
  assert.equal(dry.error, 'insufficient_balance', 'the live burn path did not reach the balance check: ' + JSON.stringify(dry));
  console.log(`published @three-ws/three-token-mcp over stdio: three_burn is annotated destructiveHint=true readOnlyHint=false; without confirm it answered ${gated.error}; three_price priced $THREE at ${price.price_usd} USD via ${price.source}; with confirm:true and an empty throwaway wallet the live burn path passed the canonical $THREE mint and incinerator checks and stopped at ${dry.error} before building or signing any transaction`);
} finally { await c.close(); }
